/bin/zsh -lc "ls -la && python3 - <<'PY'
import json
from pathlib import Path
for name in ['source.json','policy.json','coordination.json']:
 p=Path(name)
 x=json.loads(p.read_text())
 print(name, 'bytes', p.stat().st_size, 'type',type(x).__name__)
 if isinstance(x,dict): print('keys',list(x))
 if name"'!='"'source.json': print(json.dumps(x,ensure_ascii=False,indent=2))
 else:
  if isinstance(x,list):
   for n,a in enumerate(x): print(n,list(a),a.get('number'),len(a.get('source_xml','')),len(a.get('source_notes_xml','') or ''))
PY"

